import{_ as s,l,o,c as i,v as E,p as h,x as r,d as e,i as d,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"高频预测的损失函数","description":"","frontmatter":{"title":"高频预测的损失函数","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hf-forecast-loss.md","filePath":"quant/hf-forecast-loss.md","lastUpdated":1789023840000}'),A={name:"quant/hf-forecast-loss.md"};function c(u,t,B,f,m,b){const n=l("Mermaid");return o(),i("div",null,[t[1]||(t[1]=E('<h1 id="高频预测的损失函数" tabindex="-1">高频预测的损失函数 <a class="header-anchor" href="#高频预测的损失函数" aria-label="Permalink to &quot;高频预测的损失函数&quot;">​</a></h1><div class="epigraph"><p>评的是哪一个对象、在哪一个时钟上、用哪一个带噪代理；损失一旦与对象错位，预平均、HAR 与 GARCH 的胜负只是在比较两种偏差。</p><footer>—— Patton, Volatility Forecast Comparison Using Imperfect Volatility Proxies, Journal of Econometrics, 2011；高频应用须把代理换成噪声修正后的已实现量</footer></div><p><a href="/quant/business-time-clock">业务时间</a> 把格重标；<a href="/quant/qlike-vol-forecast-eval">QLIKE</a> 已给日频纪律。本课是「金融计量与高频统计」的收束：把 Patton 的正当损失放到 <strong>IV / 已实现协方差 / 下一根 bar 方差</strong> 上，并锁死代理（TSRV、核、预平均）、同步（刷新/HY）与时钟（墙钟 vs 成交量）。缺口是：高频里代理更噪、跳跃更尖、样本外切分更易泄漏（用未来 tick 定阈值）。下一课程是衍生品进阶，默认本课的对象声明已经做完——不再用 tick 平方当无偏 \\(IV\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预测 \\(\\hat h_{t,i}\\)：下一格、下一小时、或次日 \\(IV\\)。代理 \\(x\\)：朴素 RV、TSRV、核、预平均、半方差。Patton：仅当损失对不完美代理稳健且 \\(x\\) 对真对象无偏（或偏差与 \\(h\\) 无关）时，排序才一致。高频朴素 RV <strong>有偏</strong>（\\(+2n\\sigma_\\varepsilon^2\\)），QLIKE 也不能挽救「谁更贴近噪声」。必须先用本单元的一致估计当 \\(x\\)，或接受评的是「含噪二次变差」并两边同一偏。</p><p>问题还含：多资产 Frobenius vs 多元 QLIKE；含跳 vs 连续；日历日 vs 下一 dollar bar。每一条都换对象。</p><h3 id="锁定三件套" tabindex="-1">锁定三件套 <a class="header-anchor" href="#锁定三件套" aria-label="Permalink to &quot;锁定三件套&quot;">​</a></h3><ol><li><strong>对象</strong>：连续 \\(IV\\)、总二次变差、\\(\\Sigma\\)、\\(\\beta\\)、下一格 \\(\\sigma^2\\)。</li><li><strong>代理</strong>：与对象匹配的估计量（预平均 IV 评预平均预测；不要用五分钟评 tick 模型还声称评了 \\(IV\\)）。</li><li><strong>时钟与样本外</strong>：墙钟滚动；业务时间则阈值不得用测试段未来量。块 DM、HAC 滞后按重叠格数。</li></ol><p><span class="marginnote">用全天核 \\(IV\\) 去评盘中逐格预测，是用积分评瞬时，偏差系统。格内预测的代理应是后续窗的已实现量，窗宽与预测地平线一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>一元格/日。</strong> QLIKE\\((h,x)\\)，\\(x\\) 为噪声修正 RV。并列 MSE 作对照，但不单用 MSE 选模。跳跃日：并列 BV 代理，或声明对象含跳。</p><p><strong>矩阵。</strong> Laurent、Rombouts、Violante 等讨论的多元损失；Wishart QLIKE。代理 = 同一刷新规则下的已实现协方差。不正定代理先投影再评，两边一致。</p><p><strong>推断。</strong> DM + HAC；多模型 SPA。嵌套（HAR 对 AR(1) RV）用 Clark–West 或自助。高频观测数 \\(n\\) 大不是独立信息量——长期依赖与重叠仍在，不要用 \\(\\sqrt n\\) 当功效幻想。</p><p><strong>校准。</strong> MZ：\\(x=a+b\\hat h+e\\)，HAC。\\(b\\lt 1\\) 仍可能是代理噪声衰减。看 QLIKE 为主。</p><h3 id="与执行、定价" tabindex="-1">与执行、定价 <a class="header-anchor" href="#与执行、定价" aria-label="Permalink to &quot;与执行、定价&quot;">​</a></h3><p>执行关心成交路径方差，代理应用成交价已实现量，不是中点 IV。期权方差互换更近总二次变差含跳。对象写进损失，才能避免「核 IV 赢了所以拿去对冲成交」。这是本栏微观结构与定价的交界，不把对冲误差公式再推一遍。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正当评分：真条件期望最小化期望损失。代理无偏时噪声平均掉。高频失败模式是代理有偏且偏依赖模型（密采样模型更贴近噪声，MSE 会奖它）。机制上必须先减偏。时钟错位：业务时间模型在墙钟 QLIKE 下像「开盘永远预测高」，那是季节，不是方差技巧。</p><p>泄漏：用测试日的成交量定 bar 阈值、用全样本估季节 \\(s_i\\)、用全天核去设盘中带宽，都会把测试信息写进 \\(\\hat h\\)。每条自助或滚动路径必须重估季节与带宽，接 <a href="/quant/bootstrap-finance">bootstrap</a> 课。</p><p><span class="marginnote">Hansen SPA 在高频里模型数爆炸（网格×核×时钟）。预登记少数候选，否则 SPA 的原假设「没有优于基准」在搜出来的集合上没有定义。</span></p><h3 id="课程收束" tabindex="-1">课程收束 <a class="header-anchor" href="#课程收束" aria-label="Permalink to &quot;课程收束&quot;">​</a></h3><p>从 <a href="/quant/ols-robust-se">OLS 稳健标准误</a> 的斜率精度，到 GMM/HJ，到 VAR/长记忆，到噪声下的 IV：贯穿的是<strong>对象与依赖结构写进推断</strong>。高频预测损失是同一原则在最后一公里：代理、HAC、聚类、重叠、时钟。衍生品课将假定 RV/IV 已经按本单元定义，不再从 tick 平方讲起。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>隔夜、午休、半日市：损失按会话加总须预先规则。最小特征值噪声让矩阵损失被一个方向主导，应因子或只评组合方差。计算：逐格 QLIKE 全市场要预算，可先评指数与流动性桶。</p><p>工程：生产默认——对象日 \\(IV\\)、代理预登记核或 TSRV、损失 QLIKE、滚动样本外、DM。盘中默认——同一时钟的下一窗已实现量。不要用 tick 平方评模型。不要跨时钟比较 \\(R^2\\)。本课结束本课程。</p>',25)),(o(),h(p,null,{default:r(()=>[d(n,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%A3%B0%E6%98%8E%E5%AF%B9%E8%B1%A1%3A%20IV%20%2F%20%CE%A3%20%2F%20%E6%A0%BC%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20PRX%5B%22%E6%97%A0%E5%81%8F%E4%BB%A3%E7%90%86%3A%20%E6%A0%B8%20%2F%20TSRV%20%2F%20%E9%A2%84%E5%B9%B3%E5%9D%87%22%5D%0A%20%20CLK%5B%22%E5%A3%B0%E6%98%8E%E6%97%B6%E9%92%9F%3A%20%E5%A2%99%E9%92%9F%E6%88%96%E4%B8%9A%E5%8A%A1%E6%97%B6%E9%97%B4%22%5D%20--%3E%20PRX%0A%20%20PRX%20--%3E%20QLIKE%5B%22QLIKE%20%E6%88%96%E5%A4%9A%E5%85%83%E6%AD%A3%E5%BD%93%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20QLIKE%20--%3E%20DM%5B%22DM%20%2F%20SPA%20%E5%9D%97%E6%8E%A8%E6%96%AD%22%5D%0A%20%20BIAS%5B%22%E6%9C%B4%E7%B4%A0%20tick%20RV%20%E4%BD%9C%E4%BB%A3%E7%90%86%22%5D%20--%3E%20WRONG%5B%22%E6%8E%92%E5%BA%8F%E5%A5%96%E5%99%AA%E5%A3%B0%E6%8B%9F%E5%90%88%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[e(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a("h2",{id:"小结",tabindex:"-1"},[e("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),t[3]||(t[3]=a("ul",null,[a("li",null,"高频预测评估必须锁定对象、噪声修正代理、时钟；Patton QLIKE 在代理有偏时同样会失灵。"),a("li",null,"样本外重估季节、带宽、bar 阈值；DM/SPA 的块对应重叠与依赖。"),a("li",null,"执行路径与中点 \\(IV\\) 是不同对象，赢的模型不能自动迁移。"),a("li",null,"本课程从回归推断到噪声下二次变差，纪律都是：先写对象，再写依赖，再报数字。"),a("li",null,[e("出处：Patton, "),a("em",null,"Journal of Econometrics"),e(", 2011；Diebold and Mariano, 1995；Hansen SPA, 2005；已实现量理论见 Andersen, Bollerslev, Diebold 与 Barndorff-Nielsen–Shephard 传统。")])],-1))])}const g=s(A,[["render",c]]);export{I as __pageData,g as default};
